HEAD=c2ac084d9a442dce243396f04de06557268bb5cd
echo "=== PR view after R2 ==="
gh pr view 6068 --json number,state,isDraft,headRefOid,baseRefName,headRefName,mergeable,mergeStateStatus,url
echo "=== timeline events (ready/draft) ==="
gh api graphql -f query='
query {
  repository(owner:"rauterfrank-ui", name:"Peak_Trade") {
    pullRequest(number:6068) {
      isDraft
      state
      timelineItems(last: 20, itemTypes: [CONVERT_TO_DRAFT_EVENT, READY_FOR_REVIEW_EVENT, CLOSED_EVENT, REOPENED_EVENT, HEAD_REF_FORCE_PUSHED_EVENT]) {
        nodes {
          __typename
          ... on ConvertToDraftEvent { createdAt }
          ... on ReadyForReviewEvent { createdAt }
          ... on ClosedEvent { createdAt }
          ... on ReopenedEvent { createdAt }
        }
      }
    }
  }
}'
echo "=== pull_request workflow runs last 5 ==="
gh api "repos/rauterfrank-ui/Peak_Trade/actions/runs?event=pull_request&per_page=5" --jq '.workflow_runs[] | {id, name, event, status, created_at, head_sha, head_branch}'
echo "=== invariant: local HEAD / remote / files / hashes ==="
git fetch origin --prune
git rev-parse HEAD
git rev-parse origin/forensics/sw-r-002-working-state-synthesis
git diff --name-only origin/main...HEAD
git diff origin/main...HEAD | shasum -a 256
shasum -a 256 docs/forensics/working_state/PEAK_TRADE_SW_R_002_WORKING_STATE.md
git status --porcelain=v1
echo "=== actions enabled ==="
gh api repos/rauterfrank-ui/Peak_Trade --jq '{private, has_actions: true}'
gh api repos/rauterfrank-ui/Peak_Trade/actions/permissions --jq .
